/**
 * AI engine — local Ollama connection.
 *
 * JARVIS talks to Ollama over its HTTP API (default http://127.0.0.1:11434),
 * so every answer is generated by a real model running on this machine:
 *
 *   browser → POST /api/chat (Next.js) → POST /api/chat (Ollama) → llama3.2
 *
 * No API key, no billing and no internet connection are required for local
 * inference. Server-only: never import from client components.
 *
 * Configuration (all optional):
 *   OLLAMA_BASE_URL   default http://127.0.0.1:11434
 *   OLLAMA_MODEL      default llama3.2
 */

export type AiRole = "system" | "user" | "assistant"

export interface AiMessage {
  role: AiRole
  content: string
}

export interface OllamaStatus {
  reachable: boolean
  baseUrl: string
  /** Installed model tags, e.g. ["llama3.2:3b"]. */
  models: string[]
  error?: string
}

/** Thrown when the local engine cannot answer. The message is shown to the
 *  user verbatim, so it must be actionable. */
export class AiUnavailableError extends Error {
  constructor(message: string) {
    super(message)
    this.name = "AiUnavailableError"
  }
}

const DEFAULT_BASE_URL = "http://127.0.0.1:11434"
const TAGS_TIMEOUT_MS = 2_500
const CHAT_TIMEOUT_MS = 10 * 60 * 1_000

export function ollamaBaseUrl(): string {
  return (process.env.OLLAMA_BASE_URL || DEFAULT_BASE_URL).replace(/\/+$/, "")
}

export function ollamaModel(): string {
  return process.env.OLLAMA_MODEL || "llama3.2"
}

/** Ask Ollama which models it has. Never throws — reports unreachable instead. */
export async function ollamaStatus(): Promise<OllamaStatus> {
  const baseUrl = ollamaBaseUrl()
  try {
    const res = await fetch(`${baseUrl}/api/tags`, {
      headers: { Accept: "application/json" },
      signal: AbortSignal.timeout(TAGS_TIMEOUT_MS),
    })
    if (!res.ok) {
      return {
        reachable: false,
        baseUrl,
        models: [],
        error: `Ollama answered with HTTP ${res.status}.`,
      }
    }
    const data = (await res.json()) as { models?: Array<{ name?: string; model?: string }> }
    const models = (data.models ?? [])
      .map((m) => String(m.name ?? m.model ?? ""))
      .filter(Boolean)
    return { reachable: true, baseUrl, models }
  } catch (err) {
    return {
      reachable: false,
      baseUrl,
      models: [],
      error: err instanceof Error ? err.message : String(err),
    }
  }
}

/**
 * Resolve the requested model against what is installed. Ollama treats
 * `llama3.2` and `llama3.2:latest` as the same tag, so match on the base name
 * as well as the exact tag.
 */
export function resolveModel(installed: string[], wanted: string): string | null {
  const target = wanted.trim()
  if (!target) return null
  if (installed.includes(target)) return target

  const exact = installed.find((m) => m.split(":")[0] === target)
  if (exact) return exact

  const base = target.split(":")[0]
  return installed.find((m) => m.split(":")[0] === base) ?? null
}

function unreachableMessage(baseUrl: string, model: string): string {
  return (
    `Local AI engine unreachable — Ollama is not answering at ${baseUrl}. ` +
    `Start it with "ollama serve" (or launch the Ollama app), then run ` +
    `"ollama pull ${model}" once. JARVIS does not fall back to canned replies.`
  )
}

function missingModelMessage(baseUrl: string, model: string, installed: string[]): string {
  return (
    `Ollama is running at ${baseUrl}, but the model "${model}" is not installed. ` +
    `Run "ollama pull ${model}" in a terminal, then try again.` +
    (installed.length > 0 ? ` Installed: ${installed.join(", ")}.` : "")
  )
}

/**
 * Convert Ollama's newline-delimited JSON stream into a plain-text stream of
 * answer deltas, which is what JARVIS's client already knows how to read.
 */
function ndjsonToText(
  body: ReadableStream<Uint8Array>
): ReadableStream<Uint8Array> {
  const decoder = new TextDecoder()
  const encoder = new TextEncoder()
  let buffer = ""

  const emit = (
    line: string,
    controller: TransformStreamDefaultController<Uint8Array>
  ) => {
    const trimmed = line.trim()
    if (!trimmed) return
    try {
      const json = JSON.parse(trimmed)
      if (typeof json?.error === "string" && json.error) {
        controller.enqueue(encoder.encode(`\n⚠ Ollama: ${json.error}`))
        return
      }
      const delta = json?.message?.content
      if (typeof delta === "string" && delta) {
        controller.enqueue(encoder.encode(delta))
      }
    } catch {
      /* partial line — the buffer keeps it until the newline arrives */
    }
  }

  return body.pipeThrough(
    new TransformStream<Uint8Array, Uint8Array>({
      transform(chunk, controller) {
        buffer += decoder.decode(chunk, { stream: true })
        const lines = buffer.split("\n")
        buffer = lines.pop() ?? ""
        for (const line of lines) emit(line, controller)
      },
      flush(controller) {
        buffer += decoder.decode()
        if (buffer.trim()) emit(buffer, controller)
      },
    })
  )
}

/**
 * Stream a real answer from the local model.
 * Throws AiUnavailableError (with a user-facing message) when Ollama is down
 * or the model is missing.
 */
export async function streamOllamaChat(
  messages: AiMessage[]
): Promise<ReadableStream<Uint8Array>> {
  const baseUrl = ollamaBaseUrl()
  const wanted = ollamaModel()

  const status = await ollamaStatus()
  if (!status.reachable) {
    throw new AiUnavailableError(unreachableMessage(baseUrl, wanted))
  }

  const model = resolveModel(status.models, wanted)
  if (!model) {
    throw new AiUnavailableError(missingModelMessage(baseUrl, wanted, status.models))
  }

  let res: Response
  try {
    res = await fetch(`${baseUrl}/api/chat`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ model, messages, stream: true }),
      signal: AbortSignal.timeout(CHAT_TIMEOUT_MS),
    })
  } catch (err) {
    throw new AiUnavailableError(
      `Could not reach Ollama at ${baseUrl} — ${err instanceof Error ? err.message : String(err)}. ` +
        `Check that "ollama serve" is running.`
    )
  }

  if (!res.ok || !res.body) {
    const detail = await res.text().catch(() => "")
    throw new AiUnavailableError(
      `Ollama rejected the request (HTTP ${res.status}). ` +
        (detail ? detail.slice(0, 300) : `Run "ollama pull ${model}" and try again.`)
    )
  }

  return ndjsonToText(res.body)
}

/** Non-streaming variant — handy for health checks and diagnostics. */
export async function ollamaComplete(messages: AiMessage[]): Promise<string> {
  const baseUrl = ollamaBaseUrl()
  const status = await ollamaStatus()
  if (!status.reachable) throw new AiUnavailableError(unreachableMessage(baseUrl, ollamaModel()))
  const model = resolveModel(status.models, ollamaModel())
  if (!model) {
    throw new AiUnavailableError(missingModelMessage(baseUrl, ollamaModel(), status.models))
  }

  const res = await fetch(`${baseUrl}/api/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ model, messages, stream: false }),
    signal: AbortSignal.timeout(CHAT_TIMEOUT_MS),
  })
  if (!res.ok) {
    throw new AiUnavailableError(`Ollama rejected the request (HTTP ${res.status}).`)
  }
  const data = (await res.json()) as { message?: { content?: string } }
  return data.message?.content ?? ""
}
